	nodeID, ok := msg.Payload["node_id"].(string)
	if !ok {
		return fmt.Errorf("missing node_id in heartbeat")
	}

	// Update last heartbeat time
	dm.nodeTracker.UpdateHeartbeat(nodeID)
	return nil
}

