166	func (dcs *DVECreationService) CreateDVENode(req *objects.DVECreationRequest) (*objects.DVECreationResponse, error) {
167		if req.StakeAmount < dcs.minStakeAmount {
168			return &objects.DVECreationResponse{
169				Success: false,
170				Error:   fmt.Sprintf("minimum stake amount is %d NRN", dcs.minStakeAmount),
171			}, nil
172		}
173	
174		if req.OwnerID == "" || req.OwnerAddress == "" {
175			return &objects.DVECreationResponse{
176				Success: false,
177				Error:   "owner ID and address are required",
178			}, nil
179		}
180	
181		dcs.mu.Lock()
182		dveNodeID := fmt.Sprintf("dve-%s", uuid.New().String()[:12])
183	
184		creation := &objects.DVECreation{
185			ID:             uuid.New().String(),
186			Name:           req.Name,
187			OwnerID:        req.OwnerID,
188			OwnerAddress:   req.OwnerAddress,
189			DVENodeID:      dveNodeID,
190			StakeAmount:    req.StakeAmount,
191			Status:         "pending",
192			TEEType:        req.TEEType,
193			TEEAttestation: req.TEEAttestation,
194			SessionKeyID:   generateSessionKeyID(),
195			Capabilities:   req.Capabilities,
196			ResourceLimits: req.ResourceLimits,
197			RegisteredAt:   time.Now(),
198			LastHeartbeat:  time.Now(),
199			UpdatedAt:      time.Now(),
200			Persistent:     req.Persistent,
201			GracePeriod:    dcs.gracePeriod,
202		}
203	
204		dcs.activeCreations[creation.ID] = creation
205		dcs.mu.Unlock()
206	
207		// Synchronously register the node in the DVE manager so it appears in the
208		// nodes list immediately — this is fast (in-memory + DB write, no I/O).
209		if dcs.dveManager != nil {
210			nodeReq := &objects.RegisterNodeRequest{
211				Name:         creation.Name,
212				TEEType:      creation.TEEType,
213				StakeAmount:  creation.StakeAmount,
214				Location:     "local-dve",
215				Capabilities: creation.Capabilities,
216			}
217			if node, err := dcs.dveManager.RegisterNode(nodeReq); err != nil {
218				log.Printf("[DVE Creation] Warning: Failed to register node in manager: %v", err)
219			} else {
220				dcs.mu.Lock()
221				creation.DVENodeID = node.ID
222				dcs.mu.Unlock()
223				log.Printf("[DVE Creation] Registered DVE node %s immediately for creation %s", node.ID, creation.ID)
224			}
225		}
226	
227		// Save initial pending record to database (no lock needed — buntdb is thread-safe)
228		if err := dcs.saveCreationToDatabase(creation); err != nil {
229			log.Printf("Warning: Failed to save DVE creation to database: %v", err)
230		}
231	
232		// Provision DVE asynchronously — container, agent, chain session
233		go dcs.provisionDVEInBackground(creation, req)
234	
235		return &objects.DVECreationResponse{
236			Success:     true,
237			DVECreation: creation,
238			Message:     "DVE node creation initiated — provisioning in background",
239		}, nil
240	}
241	
242	// provisionDVEInBackground runs in a goroutine. It does the slow work of
243	// container provisioning, DVE manager registration, KNIRVAGENT startup,
244	// and chain session establishment. Updates creation status to "active"
245	// on success or logs errors on failure.
246	func (dcs *DVECreationService) provisionDVEInBackground(creation *objects.DVECreation, req *objects.DVECreationRequest) {
247		// 1. Attempt on-chain registration (best-effort)
248		var registrationTxHash string
249		if dcs.chainClient != nil {
250			txHash, err := dcs.chainClient.RegisterDVENode(creation.DVENodeID, req.OwnerAddress, req.StakeAmount)
251			if err != nil {
252				log.Printf("[DVE Creation] Chain registration failed for %s: %v, proceeding with local provisioning", creation.ID, err)
253			} else {
254				registrationTxHash = txHash
255			}
256		}
257		creation.RegistrationTxHash = registrationTxHash
258	
259		// 2. Provision container if orchestrator is available
260		if dcs.containerOrchestrator != nil {
261			log.Printf("[DVE Creation] Provisioning container for creation %s", creation.ID)
262			container, err := dcs.containerOrchestrator.ProvisionContainer(creation.ID)
263			if err != nil {
264				log.Printf("[DVE Creation] Error provisioning container for %s: %v", creation.ID, err)
265				dcs.updateCreationStatus(creation.ID, "failed")
266				return
267			}
268	
269			// Preserve the manager node ID that was registered synchronously in
270			// CreateDVENode — container.ID is only used internally by the orchestrator
271			// and must not overwrite the stable DVENodeID that the nodes list uses.
272			managerNodeID := creation.DVENodeID
273			creation.SSHPublicKey = container.Spec.SSHPublicKey
274			creation.SSHPrivateKey = container.SSHKeys.PrivateKey
275			creation.SSHPort = container.Endpoints.SSHPort
276			creation.IPAddress = "localhost"
277			creation.ValidationPort = container.Endpoints.ValidationPort
278			creation.ErrorResPort = container.Endpoints.ErrorResPort
279	
280			// 3. Update the DVE node in the manager with container details so
281			// SSH/IP info is available for Access.  If no manager node was registered
282			// yet (no dveManager at creation time) fall back to registering now.
283			if dcs.dveManager != nil {
284				if managerNodeID != "" {
285					updates := map[string]interface{}{
286						"ip_address": creation.IPAddress,
287						"ssh_port":   creation.SSHPort,
288						"public_key": creation.SSHPublicKey,
289						"status":     "online",
290					}
291					if _, err := dcs.dveManager.UpdateNode(managerNodeID, updates); err != nil {
292						log.Printf("[DVE Creation] Warning: Failed to update DVE node details: %v", err)
293					} else {
294						log.Printf("[DVE Creation] Updated DVE node %s with container details", managerNodeID)
295					}
296				} else {
297					// Fallback: manager not wired at creation time — register now with full details
298					nodeReq := &objects.RegisterNodeRequest{
299						Name:         creation.Name,
300						TEEType:      creation.TEEType,
301						StakeAmount:  creation.StakeAmount,
302						Location:     "local-dve",
303						IPAddress:    creation.IPAddress,
304						SSHPort:      creation.SSHPort,
305						PublicKey:    creation.SSHPublicKey,
306						Capabilities: creation.Capabilities,
307					}
308					if node, err := dcs.dveManager.RegisterNode(nodeReq); err != nil {
309						log.Printf("[DVE Creation] Warning: Failed to register DVE node in tracker: %v", err)
310					} else {
311						creation.DVENodeID = node.ID
312						log.Printf("[DVE Creation] Registered DVE node %s (fallback)", node.ID)
313					}
314				}
315			}
316	
317			// 4. Auto-start KNIRVAGENT supervisor
318			if dcs.knirvagentManager != nil {
319				agentDVEID := creation.DVENodeID
320				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
321				defer cancel()
322				if err := dcs.knirvagentManager.StartAgent(startCtx, agentDVEID, 30*time.Second); err != nil {
323					log.Printf("[DVE Creation] Warning: Failed to start KNIRVAGENT supervisor for DVE %s: %v", agentDVEID, err)
324				} else {
325					creation.SupervisorAgentID = agentDVEID
326					log.Printf("[DVE Creation] KNIRVAGENT supervisor started for DVE %s (node %s)", creation.Name, agentDVEID)
327				}
328			}
329		}
330	
331		// 5. Establish chain session (best-effort)
332		chainSession, err := dcs.establishChainSession(creation)
333		if err != nil {
334			log.Printf("[DVE Creation] Warning: Failed to establish chain session: %v", err)
335		}
336	
337		// 6. Create DVE session
338		session := &objects.DVESession{
339			ID:             uuid.New().String(),
340			DVECreationID:  creation.ID,
341			DVENodeID:      creation.DVENodeID,
342			OwnerID:        creation.OwnerID,
343			SessionKey:     generateSessionKey(),
344			SessionKeyID:   creation.SessionKeyID,
345			TEEBinding:     req.TEEAttestation,
346			ChainSessionID: "",
347			Status:         "pending",
348			CreatedAt:      time.Now(),
349			ExpiresAt:      time.Now().Add(30 * time.Minute),
350		}
351	
352		if chainSession != nil {
353			session.ChainSessionID = chainSession.SessionID
354			session.Status = "active"
355			session.ExpiresAt = chainSession.ExpiresAt
356			session.PQCSignature = chainSession.PQCSignature
357		}
358	
359		now := time.Now()
360		creation.Status = "active"
361		creation.ChainSessionID = session.ChainSessionID
362		creation.ActivatedAt = &now
363		creation.UpdatedAt = now
364	
365		// 7. Update in-memory maps and persist
366		dcs.mu.Lock()
367		dcs.activeCreations[creation.ID] = creation
368		dcs.activeSessions[session.ID] = session
369		dcs.mu.Unlock()
370	
371		if err := dcs.saveCreationToDatabase(creation); err != nil {
372			log.Printf("[DVE Creation] Warning: Failed to save updated DVE creation: %v", err)
373		}
374		if err := dcs.saveSessionToDatabase(session); err != nil {
375			log.Printf("[DVE Creation] Warning: Failed to save DVE session: %v", err)
376		}
377	
378		log.Printf("[DVE Creation] DVE %s (%s) fully provisioned and active", creation.Name, creation.ID)
379	}
