381	// updateCreationStatus sets the status of an in-memory creation and persists it.
382	// Must be called from the background goroutine (not while holding the mutex).
383	func (dcs *DVECreationService) updateCreationStatus(id, status string) {
384		dcs.mu.Lock()
385		creation, exists := dcs.activeCreations[id]
386		if exists {
387			creation.Status = status
388			creation.UpdatedAt = time.Now()
389		}
390		dcs.mu.Unlock()
391	
392		if exists {
393			if err := dcs.saveCreationToDatabase(creation); err != nil {
394				log.Printf("Warning: Failed to save status update for creation %s: %v", id, err)
395			}
396		}
397	}
