471					if err := json.Unmarshal([]byte(value), &creation); err == nil {
472						if creation.OwnerID == userID {
473							found := false
474							for _, c := range userCreations {
475								if c.ID == creation.ID {
476									found = true
477									break
478								}
479							}
480							if !found {
481								userCreations = append(userCreations, &creation)
482							}
483						}
484					}
485				}
486				return true
487			})
488		})
