608		session.Status = "revoked"
609	
610		if err := dcs.saveSessionToDatabase(session); err != nil {
611			return fmt.Errorf("failed to save revoked session: %w", err)
612		}
613	
614		delete(dcs.activeSessions, sessionID)
615	
616		return nil
617	}
618	
619	func (dcs *DVECreationService) DecommissionDVENode(creationID, ownerID string) error {
620		dcs.mu.Lock()
621		defer dcs.mu.Unlock()
622	
623		creation, exists := dcs.activeCreations[creationID]
624		if !exists {
625			return fmt.Errorf("DVE creation not found: %s", creationID)
626		}
627	
628		if creation.OwnerID != ownerID {
629			return fmt.Errorf("unauthorized: not the owner of this DVE")
630		}
631	
632		creation.Status = "decommissioned"
633		creation.UpdatedAt = time.Now()
634	
635		for sessionID, session := range dcs.activeSessions {
636			if session.DVECreationID == creationID {
637				session.Status = "revoked"
638				dcs.saveSessionToDatabase(session)
639				delete(dcs.activeSessions, sessionID)
640			}
641		}
642	
643		if err := dcs.saveCreationToDatabase(creation); err != nil {
644			return fmt.Errorf("failed to save decommissioned DVE: %w", err)
645		}
646	
647		delete(dcs.activeCreations, creationID)
648	
649		return nil
650	}
651	
652	func (dcs *DVECreationService) Heartbeat(creationID string) error {
653		dcs.mu.Lock()
654		defer dcs.mu.Unlock()
655	
656		creation, exists := dcs.activeCreations[creationID]
657		if !exists {
658			return fmt.Errorf("DVE creation not found: %s", creationID)
659		}
660	
661		creation.LastHeartbeat = time.Now()
662		creation.UpdatedAt = time.Now()
663	
664		if err := dcs.saveCreationToDatabase(creation); err != nil {
665			return fmt.Errorf("failed to save heartbeat: %w", err)
666		}
667	
668		return nil
669	}
670	
671	func (dcs *DVECreationService) GetSecret(sessionID, secretKey string) (string, error) {
672		dcs.mu.RLock()
673		defer dcs.mu.RUnlock()
674	
675		if dcs.chainClient == nil {
676			return "", fmt.Errorf("chain client not configured")
677		}
678	
679		return dcs.chainClient.GetSecret(sessionID, secretKey)
680	}
681	
682	func (dcs *DVECreationService) GetStats() (*DVECreationStats, error) {
683		dcs.mu.RLock()
684		defer dcs.mu.RUnlock()
685	
686		stats := &DVECreationStats{
687			TotalCreations:  int64(len(dcs.activeCreations)),
688			ActiveCreations: dcs.countActiveCreations(),
689			ActiveSessions:  dcs.countActiveSessions(),
690			Timestamp:       time.Now(),
691		}
692	
693		return stats, nil
694	}
695	
696	type DVECreationStats struct {
697		TotalCreations  int64     `json:"total_creations"`
698		ActiveCreations int64     `json:"active_creations"`
699		ActiveSessions  int64     `json:"active_sessions"`
700		Timestamp       time.Time `json:"timestamp"`
701	}
702	
703	func (dcs *DVECreationService) establishChainSession(creation *objects.DVECreation) (*objects.ChainSession, error) {
704		if dcs.chainClient == nil {
705			return nil, fmt.Errorf("chain client not configured")
706		}
707	
708		return dcs.chainClient.CreateChainSession(creation.DVENodeID, creation.OwnerAddress)
709	}
710	
711	func (dcs *DVECreationService) loadFromDatabase() error {
712		if dcs.db == nil {
713			return fmt.Errorf("database not initialized")
714		}
715	
716		err := dcs.db.GetObjectsByPrefix("dve_creation:", func(key string, value []byte) bool {
717			var creation objects.DVECreation
718			if err := json.Unmarshal(value, &creation); err == nil {
719				if creation.Status == "active" || creation.Status == "pending" {
720					dcs.activeCreations[creation.ID] = &creation
721				}
722			}
723			return true
724		})
725		if err != nil {
726			return err
727		}
728	
729		return dcs.db.GetObjectsByPrefix("dve_session:", func(key string, value []byte) bool {
730			var session objects.DVESession
731			if err := json.Unmarshal(value, &session); err == nil {
732				if session.Status == "active" {
733					dcs.activeSessions[session.ID] = &session
734				}
735			}
736			return true
737		})
738	}
739	
740	func (dcs *DVECreationService) saveToDatabase() error {
741		if dcs.db == nil {
742			return fmt.Errorf("database not initialized")
743		}
744	
745		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
746			for _, creation := range dcs.activeCreations {
747				if data, err := json.Marshal(creation); err == nil {
748					tx.Set("dve_creation:"+creation.ID, string(data), nil)
749				}
750			}
751			for _, session := range dcs.activeSessions {
752				if data, err := json.Marshal(session); err == nil {
753					tx.Set("dve_session:"+session.ID, string(data), nil)
754				}
755			}
756			return nil
757		})
758	}
759	
760	func (dcs *DVECreationService) saveCreationToDatabase(creation *objects.DVECreation) error {
761		if dcs.db == nil {
762			return fmt.Errorf("database not initialized")
763		}
764	
765		data, err := json.Marshal(creation)
766		if err != nil {
767			return fmt.Errorf("failed to marshal creation: %w", err)
768		}
769	
770		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
771			_, _, err := tx.Set("dve_creation:"+creation.ID, string(data), nil)
772			return err
773		})
774	}
775	
776	func (dcs *DVECreationService) saveSessionToDatabase(session *objects.DVESession) error {
777		if dcs.db == nil {
778			return fmt.Errorf("database not initialized")
779		}
780	
781		data, err := json.Marshal(session)
782		if err != nil {
783			return fmt.Errorf("failed to marshal session: %w", err)
784		}
785	
786		return dcs.db.Transaction(func(tx *buntdb.Tx) error {
787			_, _, err := tx.Set("dve_session:"+session.ID, string(data), nil)
788			return err
789		})
790	}
791	
792	func (dcs *DVECreationService) countActiveCreations() int64 {
793		count := int64(0)
794		now := time.Now()
795		for _, creation := range dcs.activeCreations {
796			if creation.Status == "active" && now.Sub(creation.LastHeartbeat) < 10*time.Minute {
797				count++
798			}
799		}
800		return count
801	}
802	
803	func (dcs *DVECreationService) countActiveSessions() int64 {
804		count := int64(0)
805		now := time.Now()
806		for _, session := range dcs.activeSessions {
807			if session.Status == "active" && now.Before(session.ExpiresAt) {
808				count++
809			}
810		}
811		return count
812	}
813	
814	func (dcs *DVECreationService) cleanupRoutine() {
815		ticker := time.NewTicker(dcs.cleanupInterval)
816		defer ticker.Stop()
817	
818		for range ticker.C {
819			if !dcs.running {
820				return
821			}
822			dcs.cleanupExpiredSessions()
823		}
824	}
825	
826	func (dcs *DVECreationService) cleanupExpiredSessions() {
827		dcs.mu.Lock()
828		defer dcs.mu.Unlock()
829	
830		now := time.Now()
831		expiredCount := 0
832	
833		for id, session := range dcs.activeSessions {
834			if now.After(session.ExpiresAt) {
835				session.Status = "expired"
836				dcs.saveSessionToDatabase(session)
837				delete(dcs.activeSessions, id)
838				expiredCount++
839			}
840		}
841	
842		if expiredCount > 0 {
843			log.Printf("Cleaned up %d expired DVE sessions", expiredCount)
844		}
845	}
846	
847	// nodeHeartbeatRoutine keeps active DVE nodes alive in the DVEManager so the
848	// health-check goroutine (which marks nodes offline after 2 min without a
849	// heartbeat) does not silently hide them from the KNIRVGATEWAY WebGUI list.
850	func (dcs *DVECreationService) nodeHeartbeatRoutine() {
851		ticker := time.NewTicker(60 * time.Second)
852		defer ticker.Stop()
853	
854		for range ticker.C {
855			if !dcs.running {
856				return
857			}
858			dcs.refreshActiveNodeHeartbeats()
859		}
860	}
861	
862	func (dcs *DVECreationService) refreshActiveNodeHeartbeats() {
863		if dcs.dveManager == nil {
864			return
865		}
866	
867		dcs.mu.RLock()
868		var nodeIDs []string
869		for _, creation := range dcs.activeCreations {
870			if creation.Status == "active" && creation.DVENodeID != "" {
871				nodeIDs = append(nodeIDs, creation.DVENodeID)
872			}
873		}
874		dcs.mu.RUnlock()
875	
876		for _, nodeID := range nodeIDs {
877			if err := dcs.dveManager.HeartbeatNode(nodeID); err != nil {
878				log.Printf("[DVE Creation] Warning: Failed to refresh heartbeat for node %s: %v", nodeID, err)
879			}
880		}
881	}
882	
883	func (dcs *DVECreationService) sessionValidationRoutine() {
884		ticker := time.NewTicker(1 * time.Minute)
885		defer ticker.Stop()
886	
887		for range ticker.C {
888			if !dcs.running {
889				return
890			}
891			dcs.validateChainSessions()
892		}
893	}
894	
895	func (dcs *DVECreationService) validateChainSessions() {
896		dcs.mu.RLock()
897		sessions := make([]*objects.DVESession, 0, len(dcs.activeSessions))
898		for _, session := range dcs.activeSessions {
899			if session.Status == "active" {
900				sessions = append(sessions, session)
901			}
902		}
903		dcs.mu.RUnlock()
904	
905		if dcs.chainClient == nil {
906			return
907		}
908	
909		for _, session := range sessions {
910			_, err := dcs.chainClient.ValidateSession(session.ChainSessionID)
911			if err != nil {
912				log.Printf("Session validation failed for %s: %v", session.ChainSessionID, err)
913				dcs.mu.Lock()
914				session.Status = "expired"
915				dcs.saveSessionToDatabase(session)
916				delete(dcs.activeSessions, session.ID)
917				dcs.mu.Unlock()
918			}
919		}
920	}
921	
922	func generateSessionKey() []byte {
923		key := make([]byte, 32)
924		rand.Read(key)
925		return key
926	}
927	
928	func generateSessionKeyID() string {
929		hash := sha256.Sum256([]byte(uuid.New().String()))
930		return base64.URLEncoding.EncodeToString(hash[:])[:16]
931	}
