291	// CreateNodeSSHSession handles POST /api/dve/{nodeId}/ssh-session (Gap 1)
292	// Creates an SSH session for a DVE node so the ConsolePanel can connect via WebSocket.
293	func (h *DVEHandlers) CreateNodeSSHSession(w http.ResponseWriter, r *http.Request) {
294		vars := mux.Vars(r)
295		nodeID := vars["nodeId"]
296	
297		w.Header().Set("Content-Type", "application/json")
298	
299		if h.sessionManager == nil || h.dveManager == nil {
300			w.WriteHeader(http.StatusServiceUnavailable)
301			json.NewEncoder(w).Encode(map[string]string{"error": "session manager not available"})
302			return
303		}
304	
305		node, err := h.dveManager.GetNode(nodeID)
306		if err != nil {
307			w.WriteHeader(http.StatusNotFound)
308			json.NewEncoder(w).Encode(map[string]string{"error": "node not found"})
309			return
310		}
311	
312		// Decode optional request body for username/key overrides
313		var req struct {
314			Username   string `json:"username"`
315			PrivateKey string `json:"private_key"`
316		}
317		json.NewDecoder(r.Body).Decode(&req)
318		if req.Username == "" {
319			req.Username = "dve-admin"
320		}
321		if req.PrivateKey == "" {
322			// Use node public key as placeholder; real deployment provides actual private key
323			req.PrivateKey = node.PublicKey
324		}
325	
326		sess, err := h.sessionManager.CreateSSHSession(nodeID, node.ID, req.Username, req.PrivateKey)
327		if err != nil {
328			w.WriteHeader(http.StatusInternalServerError)
329			json.NewEncoder(w).Encode(map[string]string{"error": "failed to create session: " + err.Error()})
330			return
331		}
332	
333		// Populate endpoint details from the node
334		sess.Endpoint = node.IPAddress
335		port := node.SSHPort
336		if port == 0 {
337			port = 22
338		}
339		sess.Port = port
340	
341		json.NewEncoder(w).Encode(map[string]interface{}{
342			"session_id": sess.ID,
343			"endpoint":   sess.Endpoint,
344			"port":       sess.Port,
345			"username":   sess.Username,
346			"expires_at": sess.ExpiresAt,
347			"ws_url":     fmt.Sprintf("/ws/ssh/%s", sess.ID),
348		})
349	}
