852				}
853				w.Header().Set("Content-Type", "application/json")
854				w.WriteHeader(http.StatusNotFound)
855				json.NewEncoder(w).Encode(response)
856				return
857			} else {
858				response := DVENodeResponse{
859					Success:   false,
860					Error:     "Failed to fetch node: " + err.Error(),
861					Timestamp: getCurrentTimestamp(),
862				}
863				w.Header().Set("Content-Type", "application/json")
864				w.WriteHeader(http.StatusInternalServerError)
865				json.NewEncoder(w).Encode(response)
866				return
867			}
868		}
869	
870		endpoint := map[string]interface{}{
871			"port":     node.ValidationPort,
872			"host":     node.IPAddress,
873			"protocol": "http",
874			"url":      fmt.Sprintf("http://%s:%d", node.IPAddress, node.ValidationPort),
875		}
876	
877		response := DVENodeResponse{
878			Success:   true,
879			Data:      endpoint,
880			Message:   "Validation endpoint retrieved successfully",
881			Timestamp: getCurrentTimestamp(),
882		}
883	
884		w.Header().Set("Content-Type", "application/json")
885		json.NewEncoder(w).Encode(response)
886	}
887	
888	// GetDVENodeErrorResolutionEndpoint handles GET /api/dve-nodes/{id}/error-resolution-endpoint
889	func (h *DVEHandlers) GetDVENodeErrorResolutionEndpoint(w http.ResponseWriter, r *http.Request) {
890		vars := mux.Vars(r)
891		nodeID := vars["id"]
892	
893		if nodeID == "" {
894			response := DVENodeResponse{
895				Success:   false,
896				Error:     "Node ID is required",
897				Timestamp: getCurrentTimestamp(),
898			}
899			w.Header().Set("Content-Type", "application/json")
900			w.WriteHeader(http.StatusBadRequest)
901			json.NewEncoder(w).Encode(response)
902			return
903		}
904	
905		node, err := h.dveManager.GetNode(nodeID)
906		if err != nil {
907			if strings.Contains(err.Error(), "node not found") {
908				response := DVENodeResponse{
909					Success:   false,
910					Error:     "Node not found",
911					Timestamp: getCurrentTimestamp(),
912				}
913				w.Header().Set("Content-Type", "application/json")
914				w.WriteHeader(http.StatusNotFound)
915				json.NewEncoder(w).Encode(response)
916				return
917			} else {
918				response := DVENodeResponse{
919					Success:   false,
920					Error:     "Failed to fetch node: " + err.Error(),
921					Timestamp: getCurrentTimestamp(),
922				}
923				w.Header().Set("Content-Type", "application/json")
924				w.WriteHeader(http.StatusInternalServerError)
925				json.NewEncoder(w).Encode(response)
926				return
927			}
928		}
929	
930		endpoint := map[string]interface{}{
931			"port":     node.ErrorResPort,
932			"host":     node.IPAddress,
933			"protocol": "http",
934			"url":      fmt.Sprintf("http://%s:%d", node.IPAddress, node.ErrorResPort),
935		}
