947	
948	// GetSupervisorAgentStatus handles GET /api/dve/{nodeId}/supervisor-agent/status
949	// Returns the current health status of the KNIRVAGENT supervisor for this DVE.
950	// If the node exists but no agent is running yet, it attempts to start one (lazy provisioning).
951	func (h *DVEHandlers) GetSupervisorAgentStatus(w http.ResponseWriter, r *http.Request) {
952		w.Header().Set("Content-Type", "application/json")
953	
954		if h.knirvagentManager == nil {
955			json.NewEncoder(w).Encode(map[string]interface{}{
956				"status": "unavailable",
957				"error":  "KNIRVAGENT supervisor not configured",
958			})
959			return
960		}
961	
962		nodeID := mux.Vars(r)["nodeId"]
963	
964		// Lazy-provision: if no agent is running for THIS specific DVE, start one.
965		// Check per-DVE socket — not just "any agent running" — so that accessing a
966		// second DVE while a first DVE's agent is active still triggers provisioning.
967		if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
968			if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
969				log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for node %s (%s)", nodeID, node.Name)
970				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
971				defer cancel()
972				if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
973					log.Printf("[DVE] Lazy-provisioning failed for node %s: %v", nodeID, err)
974				}
975			}
976		}
977	
978		// Check per-DVE status
979		status := "offline"
980		if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err == nil {
981			status = "online"
982		} else if h.knirvagentManager.IsRunning() {
983			status = "initializing"
984		}
985		running := status != "offline"
986	
987		healthCtx, healthCancel := context.WithTimeout(context.Background(), 5*time.Second)
988		defer healthCancel()
989		healthErr := h.knirvagentManager.HealthCheck(healthCtx)
990		healthStatus := "healthy"
991		if healthErr != nil {
992			healthStatus = "unhealthy"
993		}
994		// Override health if we just provisioned (socket might not be ready yet)
995		if status == "initializing" {
996			healthStatus = "booting"
997		}
998	
999		json.NewEncoder(w).Encode(map[string]interface{}{
1000			"status":        status,
1001			"health":        healthStatus,
1002			"running":       running,
1003			"base_url":      h.knirvagentManager.GetBaseURL(),
1004			"agent_type":    "knirvagent",
1005			"role":          "supervisor",
1006			"node_id":       nodeID,
1007			"timestamp":     getCurrentTimestamp(),
1008		})
1009	}
1010	
1011	// GetSupervisorAgentSession handles GET /api/dve/{nodeId}/supervisor-agent/session
1012	// Returns a WebSocket URL for real-time communication with the KNIRVAGENT supervisor.
1013	// If the node exists but no agent is running, attempts lazy provisioning first.
1014	func (h *DVEHandlers) GetSupervisorAgentSession(w http.ResponseWriter, r *http.Request) {
1015		w.Header().Set("Content-Type", "application/json")
1016	
1017		nodeID := mux.Vars(r)["nodeId"]
1018	
1019		if h.knirvagentManager == nil {
1020			w.WriteHeader(http.StatusServiceUnavailable)
1021			json.NewEncoder(w).Encode(map[string]interface{}{
1022				"error": "KNIRVAGENT supervisor not configured",
1023			})
1024			return
1025		}
1026	
1027		// Lazy-provision if no agent is running for THIS specific DVE (regardless of
1028		// whether agents for other DVEs are already running).
1029		if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
1030			if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
1031				log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for session on node %s (%s)", nodeID, node.Name)
1032				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
1033				defer cancel()
1034				if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
1035					log.Printf("[DVE] Lazy-provisioning failed for session on node %s: %v", nodeID, err)
1036				}
1037			}
1038		}
1039	
1040		// Verify the agent socket exists for this specific DVE (covers both
1041		// "never started" and "failed to provision" cases).
1042		if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err != nil {
1043			w.WriteHeader(http.StatusServiceUnavailable)
1044			json.NewEncoder(w).Encode(map[string]interface{}{
1045				"error": "KNIRVAGENT not available for this DVE: " + err.Error(),
1046			})
1047			return
1048		}
1049	
1050		// The session URL points to the backend WebSocket proxy which relays
1051		// I/O between the frontend terminal and the KNIRVAGENT subprocess.
1052		wsURL := fmt.Sprintf("/ws/dve/%s/agent", nodeID)
1053	
1054		json.NewEncoder(w).Encode(map[string]interface{}{
1055			"ws_url":    wsURL,
1056			"base_url":  h.knirvagentManager.GetBaseURL(),
1057			"running":   true,
1058			"timestamp": getCurrentTimestamp(),
1059		})
1060	}
1061	
1062	// RegisterRoutes registers the DVE routes with the router
1063	func (h *DVEHandlers) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
1064		// Create a subrouter for DVE endpoints
1065		dveRouter := r.PathPrefix("/api/dve-nodes").Subrouter()
1066	
1067		// Routes with optional auth (for role-based filtering)
1068		if authMiddleware != nil {
1069			optionalAuthRouter := dveRouter.PathPrefix("").Subrouter()
1070			optionalAuthRouter.Use(authMiddleware.OptionalAuth)
1071			optionalAuthRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
1072			optionalAuthRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
1073			optionalAuthRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
1074			optionalAuthRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
1075			optionalAuthRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
1076			optionalAuthRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
1077		} else {
1078			// If no auth middleware, allow public access
1079			dveRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
1080			dveRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
1081			dveRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
1082			dveRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
1083			dveRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
1084			dveRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
1085		}
1086	
1087		// Protected routes for management
1088		if authMiddleware != nil {
1089			protectedDVERouter := dveRouter.PathPrefix("").Subrouter()
1090			protectedDVERouter.Use(authMiddleware.RequireAuth)
1091			protectedDVERouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
1092			protectedDVERouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
1093			protectedDVERouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
1094		} else {
1095			// If no auth middleware, allow all routes (for testnet mode)
1096			dveRouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
1097			dveRouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
1098			dveRouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
1099		}
1100	
1101		// /api/dve/ aliases — frontend monitor-panel and connections-panel use these paths
1102		dveAliasRouter := r.PathPrefix("/api/dve").Subrouter()
1103		dveAliasRouter.HandleFunc("/workers", h.GetDVEWorkers).Methods("GET", "OPTIONS")
1104		dveAliasRouter.HandleFunc("/{nodeId}/tasks", h.GetDVENodeTasksAlias).Methods("GET", "OPTIONS")
1105		dveAliasRouter.HandleFunc("/{nodeId}/metrics", h.GetDVENodeMetricsAlias).Methods("GET", "OPTIONS")
1106	
1107		// /api/p2p/ — P2P network topology endpoints (Gap 5)
1108		p2pRouter := r.PathPrefix("/api/p2p").Subrouter()
1109		p2pRouter.HandleFunc("/peers", h.GetP2PPeers).Methods("GET", "OPTIONS")
1110	
1111		// SSH session creation for DVE nodes — used by ConsolePanel (Gap 1)
1112		dveAliasRouter.HandleFunc("/{nodeId}/ssh-session", h.CreateNodeSSHSession).Methods("POST", "OPTIONS")
1113	
1114		// DVE Supervisor Agent (KNIRVAGENT) status and session endpoints
1115		if h.knirvagentManager != nil {
1116			dveAliasRouter.HandleFunc("/{nodeId}/supervisor-agent/status", h.GetSupervisorAgentStatus).Methods("GET", "OPTIONS")
1117			dveAliasRouter.HandleFunc("/{nodeId}/supervisor-agent/session", h.GetSupervisorAgentSession).Methods("GET", "OPTIONS")
1118		}
1119	}
