1	import React, { useEffect, useState } from 'react';
2	import { useNavigation } from '../hooks/useNavigation';
3	import api from '../utils/api';
4	import PageLayout from '../components/PageLayout';
5	import PageHeader from '../components/PageHeader';
6	import GlassyCard from '../components/GlassyCard';
7	import IframeModal from '../components/IframeModal';
8	import styles from './dve-list.module.css';
9	
10	const STATUS_COLORS = {
11	  online: '#4caf50',
12	};
13	
14	const TEE_ICONS = {
15	  sgx: '🔒',
16	  'sev-snp': '🛡️',
17	  tdx: '🔐',
18	  software: '💻',
19	  'browser-dve': '🌐',
20	};
21	
22	export default function DVEList() {
23	  const { activePage } = useNavigation('dve-list');
24	  const [searchQuery, setSearchQuery] = useState('');
25	  const [activeNodes, setActiveNodes] = useState([]);
26	  const [allNodes, setAllNodes] = useState([]);
27	  const [isLoading, setIsLoading] = useState(true);
28	  const [error, setError] = useState('');
29	  const [modal, setModal] = useState({ open: false, title: '', src: '' });
30	
31	  const handleSearch = (q) => setSearchQuery(q);
32	
33	  const fetchNodes = async () => {
34	    setIsLoading(true);
35	    setError('');
36	    try {
37	      const res = await api.get('/api/dve-nodes');
38	      const raw = res.data;
39	      const nodes = Array.isArray(raw?.data || raw?.nodes || raw) ? (raw?.data || raw?.nodes || raw) : [];
40	      setAllNodes(nodes);
41	      // Only show nodes with status === 'online' (active DVEs)
42	      setActiveNodes(nodes.filter(n => n && n.status === 'online'));
43	    } catch (e) {
44	      console.error('Failed to fetch DVE nodes:', e);
45	      setError('Could not load DVE nodes. Ensure KNIRVSERVER backend is running.');
46	      setActiveNodes([]);
47	      setAllNodes([]);
48	    } finally {
49	      setIsLoading(false);
50	    }
51	  };
52	
53	  // Fetch on mount and auto-refresh every 10 seconds so newly activated
54	  // DVEs appear without a manual page reload.
55	  useEffect(() => {
56	    fetchNodes();
57	    const interval = setInterval(fetchNodes, 10_000);
58	    return () => clearInterval(interval);
59	  }, []);
60	
61	  const openDVEExplorer = (node) => {
62	    setModal({
63	      open: true,
64	      title: `DVE File Manager — ${node.name || node.id}`,
65	      src: `/dve/${encodeURIComponent(node.id)}`,
66	    });
67	  };
68	
69	  const closeModal = () => {
70	    setModal({ open: false, title: '', src: '' });
71	  };
72	
73	  const filtered = activeNodes.filter((n) =>
74	    [n.name, n.id, n.status, n.tee_type, n.location]
75	      .filter(Boolean)
76	      .join(' ')
77	      .toLowerCase()
78	      .includes(searchQuery.toLowerCase())
79	  );
80	
81	  return (
82	    <PageLayout activePage={activePage} pageTitle="My DVEs" onSearch={handleSearch}>
83	      <PageHeader
84	        title="My DVEs"
85	        subtitle={`${activeNodes.length} active DVE${activeNodes.length !== 1 ? 's' : ''} — ${allNodes.length} total registered`}
86	        titleColor="#7c4dff"
87	      />
88	
89	      {/* Stats bar */}
90	      <div className={styles.statsBar}>
91	        <div className={styles.statCard}>
92	          <span className={styles.statValue} style={{ color: '#4caf50' }}>{activeNodes.length}</span>
93	          <span className={styles.statLabel}>Active DVEs</span>
94	        </div>
95	        <div className={styles.statCard}>
96	          <span className={styles.statValue} style={{ color: '#7c4dff' }}>{allNodes.length}</span>
97	          <span className={styles.statLabel}>Total Registered</span>
98	        </div>
99	        <div className={styles.statCard}>
100	          <button className={styles.refreshBtn} onClick={fetchNodes} title="Refresh">
101	            ↻ Refresh
102	          </button>
103	        </div>
104	      </div>
105	
106	      {/* Loading state */}
107	      {isLoading && (
108	        <div className={styles.centerState}>
109	          <div className={styles.spinner}></div>
110	          <p>Loading active DVE nodes...</p>
111	        </div>
112	      )}
113	
114	      {/* Error state */}
115	      {error && !isLoading && (
116	        <GlassyCard darker className={styles.centerState}>
117	          <div className={styles.errorIcon}>⚠️</div>
118	          <p className={styles.errorText}>{error}</p>
119	          <button className={styles.retryBtn} onClick={fetchNodes}>Retry</button>
120	        </GlassyCard>
121	      )}
122	
123	      {/* Empty state — no online DVEs */}
124	      {!isLoading && !error && filtered.length === 0 && (
125	        <GlassyCard className={styles.centerState}>
126	          <div className={styles.emptyIcon}>🖥️</div>
127	          <h3>No active DVEs</h3>
128	          <p>
129	            {searchQuery
130	              ? 'No active DVEs match your search.'
131	              : allNodes.length > 0
132	                ? `${allNodes.length} DVE node${allNodes.length !== 1 ? 's' : ''} registered but none are online. Activate a DVE from the KNIRVSERVER backend dashboard to see it here.`
133	                : 'No DVEs are registered. Use the KNIRVSERVER dashboard to create a new sovereign DVE.'}
134	          </p>
135	        </GlassyCard>
136	      )}
