func (dm *DVEManager) loadNodesFromDB() error {
	return dm.db.GetObjectsByPrefix("dve:nodes:", func(key string, value []byte) bool {
		var node objects.DVENode
		if err := json.Unmarshal(value, &node); err != nil {
